"""SQLite chunk storage and a transactionally persisted HNSW search graph."""

from __future__ import annotations

import json
import sqlite3
from contextlib import contextmanager
from typing import Sequence

import numpy as np

from .indexer import Chunk


class Store:
    """Keep source snapshots, file fingerprints, and an ANN graph in one database."""

    def __init__(self, db_path: str, dim: int):
        if dim < 1:
            raise ValueError("dim must be positive")
        self.db_path = db_path
        self.dim = dim
        self._conn = None
        self._index = None
        self._revision = None
        self._dirty = False

    @property
    def conn(self) -> sqlite3.Connection:
        if self._conn is None:
            connection = sqlite3.connect(self.db_path)
            connection.row_factory = sqlite3.Row
            connection.execute("PRAGMA foreign_keys = ON")
            connection.execute("PRAGMA journal_mode = WAL")
            self._conn = connection
            self._init_schema()
        return self._conn

    def _init_schema(self) -> None:
        self.conn.executescript("""
            CREATE TABLE IF NOT EXISTS chunks (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                path TEXT NOT NULL,
                start_line INTEGER NOT NULL,
                end_line INTEGER NOT NULL,
                text TEXT NOT NULL
            );
            CREATE INDEX IF NOT EXISTS idx_chunks_path ON chunks(path);
            CREATE TABLE IF NOT EXISTS embeddings (
                chunk_id INTEGER PRIMARY KEY,
                vector BLOB NOT NULL,
                FOREIGN KEY (chunk_id) REFERENCES chunks(id) ON DELETE CASCADE
            );
            CREATE TABLE IF NOT EXISTS files (
                path TEXT PRIMARY KEY,
                digest TEXT NOT NULL,
                size INTEGER NOT NULL,
                mtime_ns INTEGER NOT NULL,
                line_count INTEGER NOT NULL
            );
            CREATE TABLE IF NOT EXISTS configuration (
                id INTEGER PRIMARY KEY CHECK(id = 1),
                data TEXT NOT NULL
            );
            CREATE TABLE IF NOT EXISTS search_graph (
                id INTEGER PRIMARY KEY CHECK(id = 1),
                revision INTEGER NOT NULL,
                data BLOB NOT NULL
            );
        """)

    def _new_index(self):
        from usearch.index import Index

        return Index(ndim=self.dim, metric="cos", dtype="f32",
                     connectivity=16, expansion_add=128, expansion_search=64)

    def _graph(self):
        row = self.conn.execute("SELECT revision FROM search_graph WHERE id = 1").fetchone()
        revision = row[0] if row else 0
        if self._index is not None and self._revision == revision:
            return self._index
        index = self._new_index()
        if row:
            data = self.conn.execute("SELECT data FROM search_graph WHERE id = 1").fetchone()[0]
            index.load(data)
            if index.ndim != self.dim:
                raise ValueError("Embedding dimensions differ; rebuild the index with the selected model.")
        elif self.conn.execute("SELECT 1 FROM chunks LIMIT 1").fetchone():
            raise ValueError("Legacy index has no search graph; run index with --rebuild.")
        self._index = index
        self._revision = revision
        return index

    @contextmanager
    def transaction(self):
        """Publish the graph and SQL rows together, or retain the previous index."""
        connection = self.conn
        if connection.in_transaction:
            raise RuntimeError("An index transaction is already active")
        connection.execute("BEGIN IMMEDIATE")
        self._dirty = False
        try:
            yield
            revision = self._revision
            if self._dirty:
                row = connection.execute("SELECT revision FROM search_graph WHERE id = 1").fetchone()
                revision = (row[0] if row else 0) + 1
                connection.execute(
                    "INSERT INTO search_graph VALUES (1, ?, ?) "
                    "ON CONFLICT(id) DO UPDATE SET revision=excluded.revision, data=excluded.data",
                    (revision, self._index.save()),
                )
            connection.commit()
            self._revision = revision
        except BaseException:
            connection.rollback()
            self._index = None
            self._revision = None
            raise
        finally:
            self._dirty = False

    def configuration(self) -> dict | None:
        row = self.conn.execute("SELECT data FROM configuration WHERE id = 1").fetchone()
        return json.loads(row[0]) if row else None

    @contextmanager
    def snapshot(self):
        """Keep configuration, graph, and source rows on one committed revision."""
        connection = self.conn
        own_transaction = not connection.in_transaction
        if own_transaction:
            connection.execute("BEGIN")
        try:
            yield
        finally:
            if own_transaction:
                connection.rollback()

    def configure(self, configuration: dict) -> None:
        current = self.configuration()
        if current is not None and current != configuration:
            raise ValueError("Workspace, model, or chunk settings differ; use a separate database or index --rebuild.")
        if current is None and self.conn.execute("SELECT 1 FROM chunks LIMIT 1").fetchone():
            raise ValueError("Legacy index has no model identity; run index with --rebuild.")
        self.conn.execute("INSERT OR IGNORE INTO configuration VALUES (1, ?)",
                          (json.dumps(configuration, sort_keys=True),))

    def add_chunks(self, chunks: Sequence[Chunk], vectors: Sequence[Sequence[float]]) -> None:
        if len(chunks) != len(vectors):
            raise ValueError("chunks and vectors must have the same length")
        if not chunks:
            return
        matrix = np.asarray(vectors, dtype=np.float32)
        if matrix.shape != (len(chunks), self.dim):
            raise ValueError(f"Each vector must have {self.dim} dimensions")
        if not np.isfinite(matrix).all() or np.any(np.linalg.norm(matrix, axis=1) == 0):
            raise ValueError("Embedding vectors must be finite and nonzero")
        if not self.conn.in_transaction:
            with self.transaction():
                self.add_chunks(chunks, vectors)
            return
        index = self._graph()
        ids = []
        for chunk, vector in zip(chunks, matrix):
            cursor = self.conn.execute(
                "INSERT INTO chunks(path, start_line, end_line, text) VALUES (?, ?, ?, ?)",
                (chunk.path, chunk.start_line, chunk.end_line, chunk.text),
            )
            ids.append(cursor.lastrowid)
            self.conn.execute("INSERT INTO embeddings VALUES (?, ?)", (cursor.lastrowid, vector.tobytes()))
        index.add(np.asarray(ids, dtype=np.uint64), matrix, threads=2)
        self._dirty = True

    def remove_file(self, path: str) -> None:
        index = self._graph()
        ids = [row[0] for row in self.conn.execute("SELECT id FROM chunks WHERE path = ?", (path,))]
        if ids:
            index.remove(ids, threads=2)
            self._dirty = True
        self.conn.execute("DELETE FROM chunks WHERE path = ?", (path,))
        self.conn.execute("DELETE FROM files WHERE path = ?", (path,))

    def file_records(self) -> dict[str, dict]:
        return {row["path"]: dict(row) for row in self.conn.execute("SELECT * FROM files")}

    def save_file(self, path: str, digest: str, size: int, mtime_ns: int, line_count: int) -> None:
        self.conn.execute(
            "INSERT INTO files VALUES (?, ?, ?, ?, ?) ON CONFLICT(path) DO UPDATE SET "
            "digest=excluded.digest, size=excluded.size, mtime_ns=excluded.mtime_ns, line_count=excluded.line_count",
            (path, digest, size, mtime_ns, line_count),
        )

    def search(self, query_vector: Sequence[float], limit: int = 10) -> list[dict]:
        if limit < 1:
            raise ValueError("limit must be positive")
        vector = np.asarray(query_vector, dtype=np.float32)
        if vector.shape != (self.dim,) or not np.isfinite(vector).all() or np.linalg.norm(vector) == 0:
            raise ValueError(f"Query must be a finite, nonzero vector of {self.dim} dimensions")
        with self.snapshot():
            index = self._graph()
            if not len(index):
                return []
            matches = index.search(vector, count=min(limit, len(index)), exact=False, threads=2)
            results = []
            for key, distance in zip(matches.keys, matches.distances):
                if distance >= 0.5:
                    continue
                row = self.conn.execute(
                    "SELECT id, path, start_line, end_line, text FROM chunks WHERE id = ?", (int(key),)
                ).fetchone()
                if row is not None:
                    results.append({**dict(row), "distance": float(distance)})
            return results

    def clear(self) -> None:
        if not self.conn.in_transaction:
            with self.transaction():
                self.clear()
            return
        self._index = self._new_index()
        row = self.conn.execute("SELECT revision FROM search_graph WHERE id = 1").fetchone()
        self._revision = row[0] if row else 0
        self._dirty = True
        for table in ("embeddings", "chunks", "files", "configuration"):
            self.conn.execute(f"DELETE FROM {table}")

    def close(self) -> None:
        if self._conn is not None:
            self._conn.close()
            self._conn = None
        self._index = None
        self._revision = None

    def __enter__(self) -> Store:
        return self

    def __exit__(self, *args: object) -> None:
        self.close()

"""Copy user-selected text through an installed clipboard utility or OSC 52."""

from __future__ import annotations

import base64
import os
import shutil
import subprocess


def copy_to_clipboard(text: str) -> bool:
    """Return whether a local clipboard utility accepted the text."""
    choices = []
    if os.environ.get("WAYLAND_DISPLAY"):
        choices.append(["wl-copy"])
    if os.environ.get("DISPLAY"):
        choices.extend([["xclip", "-selection", "clipboard"], ["xsel", "--clipboard", "--input"]])
    if os.name != "nt":
        choices.append(["pbcopy"])
    for command in choices:
        if shutil.which(command[0]) is None:
            continue
        try:
            subprocess.run(command, input=text.encode("utf-8"), timeout=2, check=True,
                           stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        except (OSError, subprocess.SubprocessError):
            continue
        return True
    return False


def clipboard_sequence(text: str) -> str:
    """Construct a trusted clipboard control, never accepting raw escape data."""
    encoded = base64.b64encode(text.encode("utf-8")).decode("ascii")
    return f"\x1b]52;c;{encoded}\x07"

"""Read scoped guidance for permitted paths before model or tool activity."""

from __future__ import annotations

from .prompts import load_prompt

import fnmatch
import os
import json
from pathlib import Path
from typing import Any

from .workspace import Workspace, WorkspaceError

INSTRUCTION_FILES = (
    "CLAUDE.md", "AGENTS.md", "AGENTS.override.md", ".cursorrules", ".clinerules",
    ".windsurfrules", ".github/copilot-instructions.md",
)
INSTRUCTION_DIRECTORIES = (
    (".cursor/rules", "*.mdc"),
    (".claude/rules", "*.md"),
    (".github/instructions", "*.instructions.md"),
    (".clinerules", "*"),
    (".windsurf/rules", "*.md"),
)


def _present(workspace: Workspace, relative: str) -> bool:
    try:
        (workspace.root / relative).lstat()
    except FileNotFoundError:
        return False
    except OSError as exc:
        raise WorkspaceError(f"cannot inspect project instructions {relative}: {exc}") from exc
    return True


def load_project_instructions(workspace: Workspace, scope: str = ".") -> str:
    """Read guidance within a scope, preserving path-labelled text.

    Also used by the session instruction tracker before each working request.
    """
    sources: list[str] = []
    seen: set[Path] = set()
    base = Path(workspace.relative(workspace.resolve(scope)))

    def read(relative: str) -> None:
        try:
            path = workspace.resolve(relative)
            if Path(relative).name == ".clinerules" and path.is_dir():
                return
            if not path.is_file():
                raise WorkspaceError("instruction path must be a regular file")
            if path in seen:
                return
            content = path.read_text(encoding="utf-8")
        except (OSError, UnicodeError, RuntimeError, WorkspaceError) as exc:
            raise WorkspaceError(f"cannot read project instructions {relative}: {exc}") from exc
        seen.add(path)
        sources.append(load_prompt('instruction-file.md', path=relative, content=content))

    for filename in INSTRUCTION_FILES:
        relative = (base / filename).as_posix()
        if _present(workspace, relative):
            read(relative)

    for directory, pattern in INSTRUCTION_DIRECTORIES:
        relative = (base / directory).as_posix()
        if not _present(workspace, relative):
            continue
        try:
            folder = workspace.resolve(relative)
        except (OSError, RuntimeError, WorkspaceError) as exc:
            raise WorkspaceError(f"cannot inspect project instructions {relative}: {exc}") from exc
        if not folder.is_dir():
            if directory == ".clinerules":
                continue
            raise WorkspaceError(f"project instruction directory is not a directory: {relative}")

        def walk_error(exc: OSError) -> None:
            raise WorkspaceError(f"cannot discover project instructions in {relative}: {exc}") from exc

        paths = []
        for current, _, filenames in os.walk(folder, onerror=walk_error, followlinks=False):
            for filename in filenames:
                if fnmatch.fnmatchcase(filename, pattern):
                    suffix = (Path(current) / filename).relative_to(folder)
                    paths.append((Path(relative) / suffix).as_posix())
        for name in sorted(paths):
            read(name)
    return "\n\n".join(sources)


class ProjectInstructions:
    """Track visited scopes and which exact guidance reached a model request."""

    def __init__(self, workspace: Workspace) -> None:
        self.workspace = workspace
        self.scopes: set[str] = {"."}
        self.delivered: dict[str, str] = {}

    def snapshot(self) -> dict[str, str]:
        result = {".": load_project_instructions(self.workspace)}
        for scope in sorted(self.scopes - {"."}):
            # Retain inaccessible scopes for a later access-mode change.
            if Path(scope).is_absolute() and not self.workspace.allows(Path(scope).resolve()):
                continue
            directory = self.workspace.resolve(scope)
            if directory.exists():
                # Scope controls applicability, while the original workspace
                # controls confinement, including links to shared parent rules.
                result[scope] = load_project_instructions(self.workspace, scope)
            else:
                result[scope] = ""
        return result

    def presented(self, snapshot: dict[str, str]) -> None:
        self.delivered = dict(snapshot)

    def guard(self, tool: Any, raw: str | dict[str, Any] | None) -> str | None:
        parameter = tool.instruction_path
        if parameter is None:
            return None
        try:
            arguments = json.loads(raw) if isinstance(raw, str) else raw or {}
        except ValueError:
            return None  # The ordinary argument validator reports syntax errors.
        if not isinstance(arguments, dict):
            return None
        relevant = {"."}
        targets = (tool.instruction_targets(arguments) if hasattr(tool, "instruction_targets")
                   else [arguments.get(parameter) or "."])
        for value in targets:
            if not isinstance(value, str):
                continue
            target = self.workspace.resolve(value)
            directory = target if target.is_dir() else target.parent
            while directory != self.workspace.root:
                relevant.add(self.workspace.relative(directory))
                if directory == directory.parent:
                    break
                directory = directory.parent
        self.scopes.update(relevant)
        if tool.mutates_workspace:
            current = self.snapshot()
            changed = [scope for scope in sorted(relevant)
                       if current.get(scope, "") != self.delivered.get(scope, "")]
            if changed:
                return (load_prompt('project-instructions-changed.md', scopes=', '.join(changed)))
        return None

    @staticmethod
    def render(snapshot: dict[str, str]) -> str:
        sections = []
        for scope, content in snapshot.items():
            if content:
                sections.append(load_prompt('instruction-scope.md', scope=scope, content=content))
        if not sections:
            return ""
        return (load_prompt('project-instructions-current.md', scopes='\n\n'.join(sections)))

"""Explicit ownership and cancellation-safe, idempotent asynchronous teardown.

Closing runs in a retained task. Cancelling a waiter never cancels cleanup;
the waiter propagates cancellation only after owned work has been drained.
This module is part of the stable frame so a reload cannot replace an active
resource's ownership bookkeeping.
"""

from __future__ import annotations

import asyncio
import inspect
from collections.abc import Callable, Coroutine
from typing import Any, TypeVar

T = TypeVar("T")


async def finish_cleanup(task: asyncio.Task[T]) -> T:
    """Await one owned cleanup to completion even if this waiter is cancelled."""
    cancellation: asyncio.CancelledError | None = None
    while not task.done():
        try:
            await asyncio.shield(task)
        except asyncio.CancelledError as exc:
            cancellation = exc
        except BaseException:
            break
    if cancellation is not None:
        try:
            task.result()
        except BaseException as exc:
            raise cancellation from exc
        raise cancellation
    return task.result()


class Lifetime:
    """Own pending tasks and LIFO cleanups; all close callers share settlement."""

    def __init__(self, name: str) -> None:
        self.name = name
        self._callbacks: list[Callable[[], Any]] = []
        self._tasks: set[asyncio.Task[Any]] = set()
        self._closing: asyncio.Task[None] | None = None

    @property
    def active(self) -> bool:
        return self._closing is None

    def defer(self, callback: Callable[[], Any]) -> None:
        if not self.active:
            raise RuntimeError(f"Lifetime {self.name} is closed")
        self._callbacks.append(callback)

    def spawn(self, operation: Coroutine[Any, Any, T]) -> asyncio.Task[T]:
        if not self.active:
            operation.close()
            raise RuntimeError(f"Lifetime {self.name} is closed")
        task = asyncio.create_task(operation, name=self.name)
        self._tasks.add(task)
        task.add_done_callback(self._settled)
        return task

    def _settled(self, task: asyncio.Task[Any]) -> None:
        self._tasks.discard(task)
        if not task.cancelled() and task.exception() is not None:
            task.get_loop().call_exception_handler({
                "message": f"Unhandled owned task failure in {self.name}",
                "exception": task.exception(), "task": task,
            })

    async def _close(self) -> None:
        tasks = tuple(self._tasks)
        for task in tasks:
            task.cancel()
        if tasks:
            await asyncio.gather(*tasks, return_exceptions=True)
        failure: BaseException | None = None
        while self._callbacks:
            callback = self._callbacks.pop()
            try:
                result = callback()
                if inspect.isawaitable(result):
                    await result
            except BaseException as exc:
                if failure is None:
                    failure = exc
        if failure is not None:
            raise failure

    async def aclose(self) -> None:
        if self._closing is None:
            self._closing = asyncio.create_task(self._close(), name=f"close {self.name}")
        await finish_cleanup(self._closing)

"""Detect repeated tool batches with unchanged results, without deduplicating calls."""

from __future__ import annotations

from .prompts import load_prompt

import hashlib
import json
import re
import copy
from typing import Any
from collections.abc import Sequence

from .api import APIResponseError
from .tools.base import ToolRegistry, ToolResult
from .types import ToolCall, decode_json_content
from .data_text import render_data


class LoopGuard:
    def __init__(self) -> None:
        self.signature: str | None = None
        self.count = 0

    def reset(self) -> None:
        self.signature = None
        self.count = 0
        self.recent: list[tuple[str, int, tuple[str, ...]]] = []
        self.recent_calls: dict[int, list[dict[str, Any]]] = {}

    def observe(self, batch: Sequence[tuple[ToolCall, ToolResult]], registry: ToolRegistry,
                step_id: int) -> tuple[str, bool]:
        records = []
        calls = []
        for call, result in batch:
            tool = registry.get(call.name)
            if getattr(tool, "progress_exempt", False):
                continue
            if call.name == "run_command" and call.arguments.get("poll") is True:
                continue
            content = result.content
            archive = registry.services.get("command_archive")
            if archive is not None and isinstance(content, str):
                # Log IDs vary even when stdout/stderr are unchanged. Remove
                # only the actual archive's exact invocation-specific notice.
                for log in reversed(list(archive.logs.values())):
                    if log.step_id == step_id and log.call_id == call.id:
                        content = content.removesuffix("\n" + log.notice())
                        break
            records.append((call.name, call.arguments, result.is_error, content))
            calls.append(call.to_record())
        if not records:
            self.reset()
            return "", False
        encoded = json.dumps(records, sort_keys=True, ensure_ascii=True).encode()
        signature = hashlib.sha256(encoded).hexdigest()
        if not hasattr(self, "recent_calls"):
            self.recent = []  # Older generations did not retain exact calls.
            self.recent_calls = {}
        self.recent.append((signature, step_id, tuple(record[0] for record in records)))
        self.recent = self.recent[-24:]
        self.recent_calls[step_id] = copy.deepcopy(calls)
        self.recent_calls = {step: self.recent_calls[step] for _, step, _ in self.recent}
        self.count = self.count + 1 if signature == self.signature else 1
        self.signature = signature
        signatures = [item[0] for item in self.recent]
        period = next((size for size in range(1, 7)
                       if len(signatures) >= size * 3
                       and signatures[-size:] == signatures[-size * 2:-size]
                       == signatures[-size * 3:-size * 2]), 0)
        if not period:
            return "", False
        stopping = (len(signatures) >= period * 4
                    and signatures[-period:] == signatures[-period * 4:-period * 3])
        names = ", ".join(dict.fromkeys(name for item in self.recent[-period:] for name in item[2]))
        if not stopping:
            return (
                load_prompt('repeated-tools.md', tool_names=names,
                            first_step=self.recent[-period * 3][1], last_step=step_id,
                            tool_calls=render_data([
                                {"step": step, "tool_calls": decode_json_content(self.recent_calls[step])}
                                for _, step, _ in self.recent[-period:]
                            ])), False,
            )
        return (
            "Stopped: the same tool batch or cycle returned unchanged results again after recovery guidance. "
            "History is preserved. Give a correction or continue to try another approach.", True,
        )


class StreamLoopError(APIResponseError):
    """A response repeats itself; its partial calls must never execute."""


class StreamLoopGuard:
    """Detect sustained exact prose repetition independently of SSE chunk sizes."""

    def __init__(self) -> None:
        self.buffers: dict[str, str] = {}
        self.checked: dict[str, int] = {}
        self.pending = ""
        self.fence = ""

    @staticmethod
    def _prose(line: str) -> bool:
        return not re.match(r"^(?: {4}|\t|\s*(?:[|#]|[-*+]\s|\d+[.)]\s|[={}\[\]]|`{3,}|~{3,}))", line)

    def feed(self, kind: str, text: str) -> None:
        if kind not in {"content", "reasoning"} or not text:
            return
        if kind == "content":
            lines = (self.pending + text).split("\n")
            self.pending = lines.pop()
            if len(self.pending) > 32768:
                self.pending = self.pending[:256] + self.pending[-32512:]
            for line in lines:
                marker = re.match(r"^\s*(`{3,}|~{3,})", line)
                if marker:
                    if not self.fence:
                        self.fence = marker[1]
                    elif marker[1][0] == self.fence[0] and len(marker[1]) >= len(self.fence):
                        self.fence = ""
                elif not self.fence and self._prose(line):
                    self.buffers[kind] = (self.buffers.get(kind, "") + line + "\n")[-32768:]
        else:
            self.buffers[kind] = (self.buffers.get(kind, "") + text)[-32768:]
        self.checked[kind] = self.checked.get(kind, 0) + len(text)
        if self.checked[kind] >= 256:
            self.check(kind)
            self.checked[kind] = 0

    def check(self, kind: str) -> None:
        text = self.buffers.get(kind, "")
        if kind == "content" and not self.fence and self._prose(self.pending):
            text += self.pending
        text = re.sub(r"\s+", " ", text).strip()[-16384:]
        if len(text) < 480:
            return
        anchor = text[-64:]
        start = max(0, len(text) - 2112)
        end = len(text) - 64
        while (match := text.rfind(anchor, start, end)) >= start:
            period = len(text) - 64 - match
            if 80 <= period <= 2048 and len(text) >= period * 6:
                unit = text[-period:]
                if text[-period * 6:] == unit * 6:
                    raise StreamLoopError(
                        f"Stopped: sustained repetition in the model's {kind} response. "
                        "No tools from this response ran; accepted history is preserved."
                    )
            end = match

    def finish(self) -> None:
        for kind in self.checked:
            self.check(kind)

"""Session-owned command logs with a shared disk quota and bounded text pages.

Commands keep draining after quota or disk failure so logging cannot deadlock a
child. Earlier bytes are never evicted to make room for newer commands. Stream
offsets count UTF-8 bytes; page limits count decoded characters. Invalid process
bytes have already been replaced by the capture decoder before arriving here.
"""

from __future__ import annotations

from ..prompts import load_prompt

import json
import os
import tempfile
import uuid
from collections.abc import Callable, Iterator
from pathlib import Path
from typing import Any, BinaryIO

from .base import Tool, ToolResult, current_invocation


MAX_OUTPUT_CHARS = 32_000_000


class OutputStream:
    def __init__(self) -> None:
        self.path: Path | None = None
        self.file: BinaryIO | None = None
        self.retained_bytes = 0
        self.lost_bytes = 0
        self.error = ""


class CommandLog:
    def __init__(self, archive: CommandArchive, command: str, step_id: int | None, call_id: str | None) -> None:
        self.archive = archive
        self.id = uuid.uuid4().hex
        self.command = command
        self.step_id = step_id
        self.call_id = call_id
        self.streams = {name: OutputStream() for name in ("stdout", "stderr")}
        self.returncode: int | None = None
        self.timed_out = False
        self.finished = False
        self.artifact_kind = "command_output"

    def write(self, name: str, text: str) -> None:
        stream = self.streams[name]
        raw = text.encode("utf-8")
        if not raw:
            return
        if stream.error:
            stream.lost_bytes += len(raw)
            return
        remaining = max(0, self.archive.quota_bytes - self.archive.used_bytes)
        # Never leave half a character at the retention boundary. Once bytes are
        # lost this stream stays stopped, so a file always represents one prefix.
        kept = raw[:remaining].decode("utf-8", errors="ignore").encode("utf-8")
        written = 0
        try:
            if kept:
                if stream.file is None:
                    stream.path = self.archive.directory / (self.id + "-" + name)
                    fd = os.open(stream.path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
                    stream.file = os.fdopen(fd, "wb", buffering=0)
                while written < len(kept):
                    count = stream.file.write(kept[written:])
                    if not count:
                        raise OSError("log write made no progress")
                    written += count
            if len(kept) < len(raw):
                stream.error = f"Session log quota of {self.archive.quota_bytes} bytes reached; later bytes from this stream are not archived."
        except OSError as exc:
            stream.error = f"Log storage failed: {exc}; later bytes from this stream are not archived."
        valid_written = len(kept[:written].decode("utf-8", errors="ignore").encode("utf-8"))
        stream.retained_bytes += valid_written
        self.archive.used_bytes += written
        stream.lost_bytes += len(raw) - valid_written

    def finish(self, returncode: int | None, timed_out: bool) -> None:
        if self.finished and self.returncode == returncode and self.timed_out == timed_out:
            return
        self.returncode = returncode
        self.timed_out = timed_out
        self.finished = True
        for stream in self.streams.values():
            if stream.file is not None:
                if getattr(self.archive, "_persistent", None) is not None:
                    try:
                        os.fsync(stream.file.fileno())
                    except OSError as exc:
                        stream.error = f"{stream.error} Output durability could not be verified: {exc}".strip()
                stream.file.close()
                stream.file = None
        store = getattr(self.archive, "artifacts", None)
        if store is not None and not hasattr(self, "artifact_record"):
            try:
                output = self.streams["stdout"]
                error = self.streams["stderr"]
                def chunks(path: Path | None, suffix: str = "") -> Iterator[str]:
                    if path is not None:
                        with path.open(encoding="utf-8", newline="") as source:
                            while chunk := source.read(4096):
                                yield chunk
                    if suffix:
                        yield suffix
                self.artifact_record = store.save(self.command, chunks(output.path),
                    error=chunks(error.path, "\n" + "\n".join(stream.error for stream in self.streams.values() if stream.error)
                                 if any(stream.error for stream in self.streams.values()) else ""),
                    kind=getattr(self, "artifact_kind", "command_output"), step_id=self.step_id, call_id=self.call_id)
            except (OSError, UnicodeError, ValueError) as exc:
                self.artifact_error = str(exc)
        callback = getattr(self.archive, "on_log", None)
        if callback is not None:
            callback(self)

    def metadata(self) -> dict[str, Any]:
        return {**({"artifacts": [self.artifact_record]} if hasattr(self, "artifact_record") else {}),
                **({"artifact_error": self.artifact_error} if hasattr(self, "artifact_error") else {}),
                "log_id": self.id, "step_id": self.step_id, "call_id": self.call_id,
                "command": self.command,
                "command_characters": len(self.command), "returncode": self.returncode,
                "timed_out": self.timed_out, "finished": self.finished,
                "streams": {name: {"retained_bytes": stream.retained_bytes,
                                    "lost_bytes": stream.lost_bytes, "retention_error": stream.error}
                            for name, stream in self.streams.items()}}

    def notice(self) -> str:
        errors = " ".join(f"{name}: {stream.error} Lost {stream.lost_bytes} UTF-8 bytes."
                          for name, stream in self.streams.items() if stream.error)
        arguments = json.dumps({"log_id": self.id, "stream": "stdout"})
        return load_prompt("command-output-recovery.md", log_id=self.id, arguments=arguments,
            retention=load_prompt("command-output-saved.md" if getattr(self.archive, "_persistent", None) else "command-output-temporary.md"),
            errors=errors).rstrip()


class CommandArchive:
    """Own files once per registry/session; reload candidates borrow this owner."""

    def __init__(self, quota_bytes: int, *, directory: Path | None = None) -> None:
        if type(quota_bytes) is not int or quota_bytes < 1:
            raise ValueError("Command archive quota must be a positive integer")
        self.quota_bytes = quota_bytes
        self.used_bytes = 0
        self.logs: dict[str, CommandLog] = {}
        self.artifacts: Any = None
        self._parent = directory
        self._temporary: tempfile.TemporaryDirectory[str] | None = None

    @property
    def directory(self) -> Path:
        persistent: Path | None = getattr(self, "_persistent", None)
        if persistent is not None:
            return persistent
        if self._temporary is None:
            self._temporary = tempfile.TemporaryDirectory(prefix="slipagent-logs-", dir=self._parent)
        return Path(self._temporary.name)

    def use_directory(self, directory: Path, on_log: Callable[[CommandLog], None]) -> None:
        """Attach private durable storage; clear detaches it without deleting it."""
        self._persistent: Path | None = directory
        self.on_log: Callable[[CommandLog], None] | None = on_log

    def start(self, command: str, *, step_id: int | None = None, call_id: str | None = None) -> CommandLog:
        invocation = current_invocation.get()
        if invocation is not None and step_id is None and call_id is None:
            step_id, call_id = invocation
        log = CommandLog(self, command, step_id, call_id)
        self.logs[log.id] = log
        callback = getattr(self, "on_log", None)
        if callback is not None:
            callback(log)
        return log

    def clear(self) -> None:
        for log in self.logs.values():
            log.finish(log.returncode, log.timed_out)
        if self._temporary is not None:
            self._temporary.cleanup()
            self._temporary = None
        self.logs.clear()
        self.used_bytes = 0
        self._persistent = None
        self.on_log = None

    async def aclose(self) -> None:
        self.clear()


class ReadCommandOutputTool(Tool):
    parameter_prompts = 'tools/read-command-output-parameters.json'
    name = "read_command_output"
    progress_exempt = True  # Re-reading a log tail is deliberate polling.
    description_prompt = 'tools/read-command-output.md'
    description = load_prompt(description_prompt)
    parameters = {"type": "object", "properties": {
        "log_id": {"type": "string"}, "step_id": {"type": "integer", "minimum": 1},
        "call_id": {"type": "string"}, "stream": {"type": "string", "enum": ["stdout", "stderr"]},
        "offset": {"type": "integer", "minimum": 0,
                   "description": ""},
        "limit": {"type": "integer", "minimum": 1, "maximum": MAX_OUTPUT_CHARS,
                  "description": ""},
        "tail": {"type": "boolean", "description": ""},
    }}

    def __init__(self, archive: CommandArchive) -> None:
        self.archive = archive

    async def run(self, *, log_id: str | None = None, step_id: int | None = None,
                  call_id: str | None = None, stream: str = "stdout", offset: int = 0,
                  limit: int = MAX_OUTPUT_CHARS, tail: bool = False) -> ToolResult:
        if log_id is None:
            records = [log.metadata() for log in self.archive.logs.values()
                       if (step_id is None or log.step_id == step_id) and (call_id is None or log.call_id == call_id)]
            # Listing offsets and limits count records, not characters.
            page = records[offset:offset + limit]
            end = offset + len(page)
            return ToolResult.ok({"logs": page, "total_logs": len(records),
                                            "offset_unit": "records", "limit_unit": "records",
                                            "next_offset": end if end < len(records) else None})
        log = self.archive.logs.get(log_id)
        if log is None:
            return ToolResult.error("Unknown command log in this session. Omit log_id to list available logs.")
        target = log.streams[stream]
        content = ""
        start = offset
        try:
            if target.path is not None:
                with target.path.open("rb") as file:
                    if tail:
                        start = max(0, target.retained_bytes - limit * 4)
                    file.seek(start)
                    raw = file.read(max(0, min(limit * 4, target.retained_bytes - start)))
                    if tail:
                        while raw and raw[0] & 0xC0 == 0x80:
                            raw, start = raw[1:], start + 1
                        text = raw.decode("utf-8")
                        content = text[-limit:]
                        start += len(text[:-limit].encode("utf-8"))
                    else:
                        # A maximum-size byte read may stop inside its final
                        # code point. Keep that code point for the next page.
                        import codecs
                        content = codecs.getincrementaldecoder("utf-8")().decode(raw, final=False)[:limit]
        except (OSError, UnicodeError) as exc:
            return ToolResult.error(f"Cannot read log at byte offset {offset}: {exc}. Use offsets returned by previous pages.")
        end = start + len(content.encode("utf-8"))
        return ToolResult.ok({"log_id": log.id, "step_id": log.step_id, "call_id": log.call_id,
            "stream": stream, "offset": start, "next_offset": end if end < target.retained_bytes else None,
            "offset_unit": "UTF-8 bytes", "limit_unit": "characters",
            "retained_bytes": target.retained_bytes, "lost_bytes": target.lost_bytes,
            "retention_error": target.error, "finished": log.finished, "returncode": log.returncode,
            "timed_out": log.timed_out, "content": content})
